#include <iostream>
#include <stdlib.h>
#include <time.h>

using std::cin;
using std::cout;
using std::endl;

int main()
{
    srand(time(nullptr));

    int iUpgrade;
    cout << "Upgrade할 장비의 단계를 입력해주세요: ";
    cin >> iUpgrade;

    float fPercent = rand() % 10001 * 0.01f;
    cout << "Percent: " << fPercent << endl;

    if (1 <= iUpgrade && iUpgrade <= 3)
    {
        cout << "강화 성공!!!" << endl;
        cout << iUpgrade++ << "단계 아이템이 " << iUpgrade << "단계가 되었습니다." << endl;
    }
    else if (4 <= iUpgrade && iUpgrade <= 6)
    {
        if (fPercent <= 40.f)
        {
            cout << "강화 성공!!!" << endl;
            cout << iUpgrade++ << "단계 아이템이 " << iUpgrade << "단계가 되었습니다." << endl;
        }
        else
        {
            cout << "강화에 실패했습니다." << endl;
        }
    }
    else if (7 <= iUpgrade && iUpgrade <= 9)
    {
        if (fPercent <= 1.f)
        {
            cout << "강화 성공!!!" << endl;
            cout << iUpgrade++ << "단계 아이템이 " << iUpgrade << "단계가 되었습니다." << endl;
        }
        else
        {
            cout << "강화에 실패했습니다." << endl;
        }
    }
    else
    {
        cout << "강화할 수 있는 단계가 아닙니다." << endl;
    }

    return 0;
}
